const lines = (xs: string[]) => xs.map(x => `— ${x}`).join('\n')
const fp = ([text, label]: [string, string?], cells: Set<string>): FormulaPart => {
  const refs = label ? refsOf(text, cells) : []
  return refs.length ? { text, label, refs } : { text, label }
}

// refs для разбора формулы выводятся из адресов в тексте части/шага: подсвечиваются только ячейки,
// которые есть в мини-листе (адреса на другие листы и в кавычках пропускаются).
const colNum = (s: string) => s.split('').reduce((n, ch) => n * 26 + ch.charCodeAt(0) - 64, 0)
const colName = (n: number) => { let s = ''; for (let m = n; m > 0; m = Math.floor((m - 1) / 26)) s = String.fromCharCode(65 + ((m - 1) % 26)) + s; return s }
const sampleCells = (sh: XlSheet | undefined): Set<string> => {
  const out = new Set<string>()
  for (const b of sh?.blocks ?? []) {
    const m = /^([A-Z]+)(\d+)$/.exec(b.at)
    if (!m) continue
    b.rows.forEach((row, i) => row.forEach((v, j) => { if (v !== null && v !== '') out.add(`${colName(colNum(m[1]) + j)}${Number(m[2]) + i}`) }))
  }
  return out
}
function refsOf(text: string, cells: Set<string>): string[] {
  const out: string[] = []
  const re = /(^|[^A-Za-z0-9_!])(\$?[A-Z]{1,2}\$?\d{1,4})(?::(\$?[A-Z]{1,2}\$?\d{1,4}))?(?![A-Za-z0-9_(])/g
  const t = text.replace(/"[^"]*"/g, '""')
  let m: RegExpExecArray | null
  while ((m = re.exec(t))) {
    const a = m[2].replace(/\$/g, ''), b = m[3]?.replace(/\$/g, '')
    if (!b) { if (cells.has(a)) out.push(a); continue }
    if (cells.has(a) && cells.has(b)) { out.push(`${a}:${b}`); continue }
    const [, c1, r1] = /^([A-Z]+)(\d+)$/.exec(a)!, [, c2, r2] = /^([A-Z]+)(\d+)$/.exec(b)!
    for (let c = colNum(c1); c <= colNum(c2); c++) for (let r = Number(r1); r <= Number(r2); r++) if (cells.has(`${colName(c)}${r}`)) out.push(`${colName(c)}${r}`)
  }
  return Array.from(new Set(out))
}

