// перед абзацем «Поменяйте и проверьте» и задание qxl в конец теста. Остальные уроки ждут вычислителя.
const LABS: Record<string, { set: TrainerSpec; ask: string; why: string }> = {
  'x07-01': { set: EXT07_TRAINERS.factsMatrix, ask: 'Матрица фактов даёт верную выручку только в первой строке, а ниже — нули. Исправьте формулу в H4: её протягивают вниз и вправо.', why: 'Период один на всю матрицу, поэтому его закрепляют полностью: $H$1. Без $ при протягивании вниз адрес уезжает на пустые ячейки H2, H3… Тренажёр проверяет вашу формулу на скрытых наборах данных.' },
  'x07-02': { set: EXT07_TRAINERS.vgoCounter, ask: 'Во второй таблице «По покупателю» для пары АБЗ → Дорстрой получился 0, хотя у покупателя сумма есть. Исправьте формулу в L12.', why: 'В столбце E второй таблицы стоят покупатели, в F — продавцы: условие по E берёт покупателя пары (J12), по F — продавца (I12). Перепутанные роли дают 0.' },
  'x07-03': { set: EXT07_TRAINERS.shares, ask: 'Расходы управляющей компании распределены верно только для Дорстроя, для остальных организаций — ошибки. Исправьте формулу в E2: её протягивают вниз.', why: 'Общую сумму $I$1 и итог выручки $B$9 закрепляют, строку выручки (B2) оставляют свободной. Без $ формула в строке 3 делит на пустую ячейку.' },
  'x07-10': { set: EXT07_TRAINERS.duplicates, ask: 'Формула помечает «дублем» оба одинаковых документа, а нужно только второй и следующие. Исправьте формулу в D2: её протягивают вниз.', why: 'Диапазон должен расти вместе со строкой: начало закреплено ($A$2), конец — нет (A2). Тогда формула считает совпадения только до текущей строки включительно.' },
}

function lesson(s: Spec): AccLesson {
  const n = s.rungs.length
  const cells = sampleCells(SAMPLES[s.key])
  const lab = LABS[s.key]
  const paras = [
    p('task', `**Вопрос из работы.** ${s.task}`),
    p('where', `**Где это у вас в работе.**\n${lines(s.where)}`),
    p('need', `**Что нужно.** Excel 2016 или новее (основной маршрут; запасной — Excel 2007/2010, см. «Какой маршрут выбрать»), Windows. ${FILE}, лист «${s.sheetName}». Голубые ячейки — исходные данные, жёлтые — готовые формулы; можно и набрать всё на чистом листе — данные приведены в уроке.`),
    p('ex', `**Исходный пример.** ${s.ex}\n${lines(s.sheet.eq)}`),
    { id: 'sheet', text: s.sheet.caption, image: excelSheet(s.sheet.title, s.sheet.rows, s.sheet.opts) },
    ...s.rungs.flatMap((r, i) => [
      p(`r${i + 1}`, `**Ступень ${i + 1} из ${n}. ${r.title}.** ${r.text}\n\`${r.formula}\`\nАнгл.: \`${r.eng}\``),
      { id: `fig${i + 1}`, text: r.caption, image: formulaFig(r.title, r.parts.map(pt => fp(pt, cells)), r.steps.map(([e, v]) => { const rf = refsOf(e, cells); return rf.length ? [e, v, rf] as [string, string, string[]] : [e, v] as [string, string] }), { sample: SAMPLES[s.key] }) },
    ]),
    p('why', `**Почему работает.** ${s.why}`),
    p('was', `**Было → стало.** ${s.was}`),
    {
      id: 'route',
      text: 'Какой маршрут выбрать: ваш вариант подсвечен по версии Excel — её можно поменять в пилюле над способами.',
      image: methodsFig({
        title: 'Способы решения',
        task: 'oneoff',
        methods: [
          { id: 'formulas', steps: [`Excel 2016 и новее: ${s.route.main}`, `Excel 2007/2010: ${s.route.old}`] },
          { id: 'modern', requires: ['dynamic-arrays'], steps: [`Excel 2021, 2024, Microsoft 365 — проверьте в своей версии: ${s.route.modern}`] },
          ...(s.route.pq ? [{ id: 'powerQuery' as const, requires: ['power-query'], steps: [`Excel 2016 и новее, если разрешено на работе: ${s.route.pq}`] }] : []),
        ],
      }),
    },
    ...(lab ? [{ id: 'trainerfig', text: 'Тренажёр: поменяйте значения и посмотрите, как меняется результат', image: trainerFig(lab.set) }] : []),
    p('trainer', `**Поменяйте и проверьте.** ${lab ? `В тренажёре выше или в своём Excel: ${s.trainer.charAt(0).toLowerCase()}${s.trainer.slice(1)}` : s.trainer}`),
    p('mist', `**Типичные ошибки.**\n${lines(s.mistakes)}`),
    p('more', `**Где подробнее в курсе.** ${s.more}`),
    p('hint', `**Подсказка.** ${s.hint}`),
    p('check', `**Проверка себя.** ${s.check}`),
    p('ai', `**Быстрее с ИИ.** ${s.ai} ${SAFE}`),
    p('src', `Источники: ${s.src}`),
  ]
  return {
    key: s.key, title: s.title, topics: s.topics, origin: [], minutes: s.minutes,
    practice: `${FILE}, лист «${s.sheetName}»; данные вымышленные`,
    software: 'Excel 2016 и новее для Windows — основной маршрут; Excel 2007/2010 — запасной (формулы файла работают с 2007, кроме помеченных)',
    applies: 'Приёмы Excel не зависят от периода; ставка НДС 22 % — с 01.01.2026 (НК РФ ст. 164 п. 3 в ред. 425-ФЗ)',
    sources: s.sources, queries: s.queries, open: s.open,
    content: { paragraphs: paras, quiz: lab ? [...s.quiz, qxl(`acc-${s.key}-q${s.quiz.length + 1}`, lab.ask, lab.set, lab.why)] : s.quiz, hardTask: s.hard },
  }
}

const AI = 'Попросите ИИ объяснить формулу по частям простыми словами и придумать два контрольных примера — на вымышленных цифрах. Если в вашем Excel нет Copilot, используйте чат с ИИ, который разрешил работодатель.'
