  topics: ['СУММЕСЛИМН', 'СУММЕСЛИ', 'оператор &', 'ПОЛУЧИТЬ.ДАННЫЕ.СВОДНОЙ.ТАБЛИЦЫ', 'таблица фактов'], minutes: 40,
  sources: ['ms-sumifs', 'ms-sumif', 'ms-index', 'ms-match', 'ms-getpivot', 'ms-alpha'],
